mockups.css:
:root{--color-primary:#1b8168;--color-on-primary:#fff;--color-primary-soft:#dcf5ec;--color-focus-ring:#1b8168;--color-accent-soft:#eaf2ce;
--color-cream:#f4f8f0;--color-stage:#edf1ea;--color-line:#e2eadf;--color-line-strong:#cbdac7;--color-paper:#fff;--color-ink:#1e2e27;
--color-ink-soft:#5c7069;--color-on-ink:#eaf2e9;--color-danger:#b23b3b;--color-danger-soft:#f6e4e2;--color-scrim:rgb(20 28 24/.55);
--color-mint:#1b8168;--color-mint-soft:#d8f0e6;--color-teal-soft:#d9ecec;
--font-serif:"Bricolage Grotesque","Segoe UI",system-ui,sans-serif;--font-sans:"Figtree","Segoe UI",system-ui,sans-serif}
body{background:#e7ede4}
.stage{font-family:var(--font-sans);color:var(--color-ink);display:flex;gap:26px;flex-wrap:wrap;justify-content:center;padding:24px 12px}
.col{display:flex;flex-direction:column;align-items:center;gap:8px}
.cap{font:600 12px var(--font-sans);color:var(--color-ink-soft);max-width:390px;text-align:center}
.phone{position:relative;width:390px;height:780px;background:var(--color-paper);border-radius:36px;border:8px solid #1e2e27;overflow:hidden;display:flex;flex-direction:column}
.topbar{height:57px;flex:none;display:flex;align-items:center;justify-content:space-between;padding:0 14px;border-bottom:1px solid var(--color-line);background:var(--color-paper)}
.brand{font:700 17px var(--font-serif)}
.icons{display:flex;gap:6px;align-items:center}
.ib{position:relative;width:40px;height:40px;border-radius:999px;border:0;background:transparent;display:flex;align-items:center;justify-content:center;font-size:19px;color:var(--color-ink)}
.ib.active{background:var(--color-mint-soft)}
.badge{position:absolute;right:-2px;top:-2px;height:18px;min-width:18px;border-radius:999px;background:var(--color-mint);color:#fff;font-size:10.5px;font-weight:800;display:flex;align-items:center;justify-content:center;padding:0 4px}
.av{width:34px;height:34px;border-radius:999px;background:var(--color-teal-soft);display:flex;align-items:center;justify-content:center;font-size:12px;font-weight:800;color:var(--color-ink)}
.av.md{width:40px;height:40px;font-size:13px}
.av.mint{background:var(--color-mint-soft)}.av.accent{background:var(--color-accent-soft)}
.scroll{flex:1;overflow-y:auto;padding:18px}
.back{font-size:12px;font-weight:700;color:var(--color-ink-soft)}
h2.p{font-size:19px;font-weight:600;margin:8px 0 2px}
.sub{font-size:12.5px;color:var(--color-ink-soft)}
.row{display:flex;gap:12px;padding:12px 4px;border-bottom:1px solid var(--color-line);align-items:flex-start}
.row .mid{flex:1;min-width:0}
.row .t{display:flex;justify-content:space-between;gap:8px;font-size:14.5px;font-weight:600}
.row .t time{font-size:11.5px;font-weight:600;color:var(--color-ink-soft);flex:none}
.row .p{font-size:12.5px;color:var(--color-ink-soft);white-space:nowrap;overflow:hidden;text-overflow:ellipsis;margin-top:2px}
.row.unread .t,.row.unread .p{font-weight:800;color:var(--color-ink)}
.chip{display:inline-block;font-size:10px;font-weight:800;border-radius:999px;padding:1px 8px;margin-right:6px;vertical-align:1px}
.chip.item{background:var(--color-accent-soft)}.chip.grp{background:var(--color-mint-soft);color:#12604D}.chip.term{background:var(--color-teal-soft)}
.count{background:var(--color-mint);color:#fff;border-radius:999px;font-size:10.5px;font-weight:800;padding:1px 7px;margin-left:6px}
.empty{margin-top:14px;border-radius:16px;border:1px dashed var(--color-line);padding:15px;font-size:12.5px;color:var(--color-ink-soft)}
.nav{height:62px;flex:none;border-top:1px solid var(--color-line);display:flex;justify-content:space-around;align-items:center;font-size:11px;color:var(--color-ink-soft);font-weight:700}
.thead{flex:none;display:flex;align-items:center;gap:10px;padding:10px 12px;border-bottom:1px solid var(--color-line)}
.thead .bk{width:36px;height:36px;border-radius:999px;border:0;background:var(--color-cream);font-size:16px}
.thumb{width:40px;height:40px;border-radius:12px;background:linear-gradient(135deg,#cbdac7,#eaf2ce)}
.thead .tt{font-size:14.5px;font-weight:700;line-height:1.2}.thead .ts{font-size:11.5px;color:var(--color-ink-soft)}
.msgs{flex:1;overflow-y:auto;padding:12px 12px 6px;background:var(--color-cream);display:flex;flex-direction:column;gap:6px}
.day{align-self:center;font-size:11px;font-weight:700;color:var(--color-ink-soft);background:var(--color-paper);border:1px solid var(--color-line);border-radius:999px;padding:2px 10px;margin:6px 0}
.b{max-width:80%;border-radius:18px;padding:8px 12px;font-size:14px;line-height:1.35;white-space:pre-line}
.b.me{align-self:flex-end;background:var(--color-primary);color:#fff;border-bottom-right-radius:6px}
.b.them{align-self:flex-start;background:var(--color-paper);border:1px solid var(--color-line);border-bottom-left-radius:6px}
.b time{display:block;font-size:10.5px;opacity:.75;margin-top:3px;text-align:right}
.who{font-size:11.5px;font-weight:800;margin:4px 0 0 42px;color:var(--color-ink-soft)}
.who .org{background:var(--color-mint-soft);color:#12604D;border-radius:999px;padding:0 6px;font-size:10px;margin-left:4px}
.line{display:flex;gap:8px;align-items:flex-end}
.composer{flex:none;border-top:1px solid var(--color-line);background:var(--color-paper);padding:10px 12px 14px}
.composer .box{display:flex;gap:8px;align-items:flex-end}
.composer textarea{flex:1;resize:none;border-radius:16px;border:1.5px solid var(--color-line);background:var(--color-cream);padding:9px 12px;font:14px var(--font-sans);height:40px}
.send{border:0;border-radius:999px;background:var(--color-primary);color:#fff;font-weight:800;font-size:13px;padding:10px 16px}
.send[disabled]{opacity:.6}
.meta{display:flex;justify-content:space-between;font-size:11px;color:var(--color-ink-soft);margin-top:5px}
.err{font-size:12px;font-weight:600;color:var(--color-danger);margin-top:6px}
.ro{flex:none;background:var(--color-stage);border-top:1px solid var(--color-line);padding:14px;font-size:12.5px;color:var(--color-ink-soft);text-align:center;font-weight:700}
.card{margin-top:16px;border-radius:16px;border:1px solid var(--color-line);background:var(--color-paper);padding:15px}
.card h3{font:700 15px var(--font-serif);margin:0}
.card .lead{font-size:12px;color:var(--color-ink-soft);margin:3px 0 10px}
.p-primary{width:100%;min-height:44px;border-radius:13px;border:0;background:var(--color-mint);color:#fff;font-size:13.5px;font-weight:800}
.pill{display:inline-flex;align-items:center;gap:6px;min-height:40px;border-radius:999px;border:1.5px solid var(--color-line);background:var(--color-paper);padding:0 14px;font-size:13px;font-weight:800;color:var(--color-ink)}
.statuscard{margin-top:12px;border-radius:16px;background:var(--color-mint-soft);padding:12px 14px;font-size:13px}
.photo{height:210px;border-radius:20px;background:linear-gradient(135deg,#cbdac7,#eaf2ce);margin-top:10px}
.krag{flex:1;overflow-y:auto;background:var(--color-cream)}
.hero{margin:0 18px;border-radius:28px;background:var(--color-primary-soft);height:150px}
.tcard{margin:14px 18px 0;border-radius:22px;border:1px solid var(--color-line);background:var(--color-paper);padding:14px;font-size:13.5px}
.chatrow{display:flex;gap:8px;margin:12px 18px 0}
.chatbtn{flex:1;min-height:44px;border-radius:999px;border:1.5px solid var(--color-line);background:var(--color-paper);font-weight:800;font-size:13px;display:flex;align-items:center;justify-content:center;gap:6px}
.footer{flex:none;border-top:1px solid var(--color-line);background:var(--color-cream);padding:12px 18px 16px}
.footer .cta{width:100%;min-height:48px;border-radius:999px;border:0;background:var(--color-primary);color:#fff;font-weight:800}
.dl{margin-top:14px;border-radius:16px;border:1px solid var(--color-line);background:var(--color-cream);padding:15px;font-size:13px}
.dl div{display:flex;justify-content:space-between;padding:3px 0}.dl dt{color:var(--color-ink-soft)}.dl dd{margin:0;font-weight:600}
.termhead{margin-top:14px;border-radius:20px;border:1px solid var(--color-line);background:var(--color-paper);padding:15px}
.sk{background:var(--color-stage);border-radius:10px}

